SINA_SMART["immuno1-immunoglobulins"] = {"lecture":"immuno1-immunoglobulins","title":"Immunoglobulins and antibody functions","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"immuno1-immunoglobulins:e0","text":"Ig = structure; antibody = function; made by B cells, soluble or BCR.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-immunoglobulins:e1","text":"2 heavy (μ, γ, α, δ, ε) + 2 light (κ, λ) chains.","topic":"Structure","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-immunoglobulins:e2","text":"Domains ~110 aa: heavy 4 (IgM, IgE 5), light 2.","topic":"Structure","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-immunoglobulins:e3","text":"Papain → 2 Fab (recognition) + 1 Fc (effector).","topic":"Structure","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-immunoglobulins:e4","text":"CDRs on a framework create diversity.","topic":"Structure","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-immunoglobulins:e5","text":"Non-covalent Ag-Ab binding.","topic":"Structure","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-immunoglobulins:e6","text":"IgM: pentamer + J chain, first response, best complement activator, no placenta.","topic":"The five classes","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-immunoglobulins:e7","text":"IgG: main serum Ig, half-life ~3 weeks, crosses placenta, opsonisation, ADCC.","topic":"The five classes","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-immunoglobulins:e8","text":"IgA: secretory dimer + J chain + secretory component; mucosal immunity.","topic":"The five classes","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-immunoglobulins:e9","text":"IgD: B-cell receptor; IgE: mast cells, allergy, parasites.","topic":"The five classes","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1gvwlvj":"a","yb0dkl":"a","8lvux3":"a","1hzqjog":"a","i1igsz":"a","wotlmm":"a","1mdlfcp":"a","k9geo":"a","17uk4w1":"a","btdyd2":"a","4v1vxy":"a","1btla43":"a","41qqf6":"a","py4kr0":"a"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"immuno1-immunoglobulins:e0":{"s":0,"u":["Ig = structure; antibody = function; made by B cells, soluble or BCR.","Immunoglobulins (Ig) are glycoproteins made by B cells, soluble or membrane-bound (the BCR); 'immunoglobulin' refers to the structure and 'antibody' to the function."],"dp":[]},"immuno1-immunoglobulins:e1":{"s":1,"u":["2 heavy (μ, γ, α, δ, ε) + 2 light (κ, λ) chains.","Each Ig has 2 heavy chains (μ, γ, α, δ, ε) and 2 light chains (κ or λ), each with variable and constant regions.","Intrachain disulfide bridges form ~110-amino-acid domains : heavy chains have 4 (5 in IgM and IgE), light chains 2."],"dp":[]},"immuno1-immunoglobulins:e2":{"s":1,"u":["Domains ~110 aa: heavy 4 (IgM, IgE 5), light 2.","Intrachain disulfide bridges form ~110-amino-acid domains : heavy chains have 4 (5 in IgM and IgE), light chains 2.","Each Ig has 2 heavy chains (μ, γ, α, δ, ε) and 2 light chains (κ or λ), each with variable and constant regions."],"dp":[]},"immuno1-immunoglobulins:e3":{"s":1,"u":["Papain → 2 Fab (recognition) + 1 Fc (effector).","Papain cuts at the hinge into 2 Fab (antigen recognition) and 1 Fc (effector binding, complement, placental transfer, catabolism)."],"dp":[]},"immuno1-immunoglobulins:e4":{"s":1,"u":["CDRs on a framework create diversity.","Variable domains have conserved framework regions carrying hypervariable loops (CDR1-3) at the tip, which contact the antigen and create diversity."],"dp":[]},"immuno1-immunoglobulins:e5":{"s":1,"u":["Non-covalent Ag-Ab binding.","Antigen-antibody binding is non-covalent : electrostatic, hydrogen bonds, Van der Waals and hydrophobic forces."],"dp":[]},"immuno1-immunoglobulins:e6":{"s":2,"u":["IgM: pentamer + J chain, first response, best complement activator, no placenta.","IgM : monomer on B cells (BCR); secreted as a pentamer with a J chain (extra CH4 domain, no hinge, 10 binding sites); ~10% of serum Ig, mainly intravascular, half-life ~5 days; first antibody of the primary response ; strongly agglutinating; most powerful activator of the classical complement pathway (switches from 'staple' to 'planar' shape on binding antigen); does not cross the placenta ; the main response to T-independent antigens."],"dp":[{"h":"Why IgM means a recent infection","t":"After a first encounter with an antigen, naive B cells make IgM first; class switching to IgG takes about a week or two. Finding specific IgM in a patient therefore points to a recent or ongoing infection, while IgG alone suggests past infection or vaccination. Serology for rubella, toxoplasmosis or hepatitis relies on this timing. Source: the lecture's IgM properties."}]},"immuno1-immunoglobulins:e7":{"s":2,"u":["IgG: main serum Ig, half-life ~3 weeks, crosses placenta, opsonisation, ADCC.","IgG : main serum class; subclasses IgG1 (45-53%), IgG2, IgG3, IgG4; half-life 21-24 days (IgG3: 7-8); complement: IgG3 > IgG1 > IgG2, IgG4 none; binds Fcγ receptors on phagocytes (opsonisation) and NK cells (FcγRIII, ADCC); crosses the placenta .","IgD : 0.25% of serum Ig, half-life 2.8 days, sensitive to proteolysis; mainly a B-cell membrane receptor, no known effector function."],"dp":[]},"immuno1-immunoglobulins:e8":{"s":2,"u":["IgA: secretory dimer + J chain + secretory component; mucosal immunity.","IgA : ~12% of serum Ig, half-life ~6 days; serum IgA is monomeric (mainly IgA1, from marrow B cells); secretory IgA is a dimer with J chain and secretory component (from the poly-Ig receptor, transported by transcytosis ), predominant in tears, saliva, colostrum, mucus (mainly IgA2); neutralises, does not activate the classical pathway, little inflammation: mucosal immunity ."],"dp":[]},"immuno1-immunoglobulins:e9":{"s":2,"u":["IgD: B-cell receptor; IgE: mast cells, allergy, parasites.","IgE : trace levels; binds mast cells and basophils; allergy and anti-parasite immunity.","IgD : 0.25% of serum Ig, half-life 2.8 days, sensitive to proteolysis; mainly a B-cell membrane receptor, no known effector function."],"dp":[]}},"meta":{"1gvwlvj":{"a":"recall","vg":"immuno1-immunoglobulins:e1/recall/1"},"yb0dkl":{"a":"recall","vg":"immuno1-immunoglobulins:e1/recall/1"},"8lvux3":{"a":"recall","vg":"immuno1-immunoglobulins:e3/recall/1"},"1hzqjog":{"a":"recall","vg":"immuno1-immunoglobulins:e3/recall/2"},"i1igsz":{"a":"recall","vg":"immuno1-immunoglobulins:e4/recall/1"},"wotlmm":{"a":"recall","vg":"immuno1-immunoglobulins:e5/recall/1"},"1mdlfcp":{"a":"recall","vg":"immuno1-immunoglobulins:e6/recall/1"},"k9geo":{"a":"recall","vg":"immuno1-immunoglobulins:e6/recall/2"},"17uk4w1":{"a":"recall","vg":"immuno1-immunoglobulins:e6/recall/3"},"btdyd2":{"a":"recall","vg":"immuno1-immunoglobulins:e7/recall/1"},"4v1vxy":{"a":"recall","vg":"immuno1-immunoglobulins:e7/recall/2"},"1btla43":{"a":"recall","vg":"immuno1-immunoglobulins:e8/recall/1"},"41qqf6":{"a":"recall","vg":"immuno1-immunoglobulins:e8/recall/2"},"py4kr0":{"a":"recall","vg":"immuno1-immunoglobulins:e9/recall/1"}},"explRev":"5cd63c4b4e14"};
